{
  "entries": [
    {
      "name_han": "子平管见",
      "logic_thesis": "命理以日主为枢纽，用神取舍不在格局虚名，而在五行生克制化能否贯通全局；管见之旨在纠偏俗说、以理驭术。",
      "logic_chain": "1) 以日干为中心建立主客关系；2) 先辨月令提纲与用神所在；3) 再看地支藏干与天干通根透出；4) 以生克制化断喜忌，不以官杀财印空套；5) 格局成败取决于气势流通，不取决于名词；6) 岁运引动原局，验其损益方成断语。",
      "logic_practice": "1) 排四柱并定日主强弱；2) 取月令用神与调候；3) 查干支通根、透干、会局；4) 立喜用忌仇并检岁运；5) 综合性情事业婚寿作断。",
      "logic_compare": "较《渊海子平》更偏纠谬与理法，较《滴天髓》少玄理而多实务；其“管见”立场近批判性子平手册，重在理通而非堆格。"
    },
    {
      "name_han": "参星秘要诹吉便览",
      "logic_thesis": "择吉以参星为主干，须将星曜吉凶与年月日时干支、神煞、方位叠合，才能在人事节点上求得趋避。",
      "logic_chain": "1) 先立所择之事类与时间窗；2) 参看主星、辅星与分野；3) 合以干支纳音与值神；4) 校验凶煞、冲破、空亡；5) 择宜时宜方，使吉星用事而凶退；6) 便览化繁为简，供速查施用。",
      "logic_practice": "1) 定用事类别（婚葬造行等）；2) 查当日参星与相关星曜；3) 对照干支神煞表；4) 排除冲克空亡；5) 选定时辰方位并记录。",
      "logic_compare": "比通书总汇更聚焦“参星+诹吉”速查，比《协纪辨方》简约而实务；属应用型星历择日，非纯命理推演。"
    },
    {
      "name_han": "奇门法窍",
      "logic_thesis": "奇门成败在“法窍”——即排盘、定局、用神、门宫星门盘之关键关节须窍通，否则有盘无断。",
      "logic_chain": "1) 依节气定阴阳遁与局数；2) 布三奇六仪与九星八门；3) 定值符值使与用神宫位；4) 看门迫宫迫、星门生克；5) 以格局与吉凶应期为断；6) 窍在关键口简明，忌繁而无主。",
      "logic_practice": "1) 定阴阳遁与局；2) 排地盘天盘人盘；3) 定用神与所问宫；4) 观门星奇仪格局；5) 断吉凶方向与应期。",
      "logic_compare": "相对《奇门遁甲统宗》等大部头，更强调关键口诀与操作窍门；与《元灵经》相比偏技法不偏玄义。"
    },
    {
      "name_han": "奇门遁甲元灵经",
      "logic_thesis": "奇门不仅是排盘术，更以“元灵”贯通天地人三才：数由气生，局由时立，断由神理与人事相应。",
      "logic_chain": "1) 元气分阴阳而立遁；2) 甲隐六仪而显三奇；3) 九宫八门应人事之门路；4) 星符仪使显天时之机；5) 灵验在心与理合，非徒记格；6) 经文以理统法，使术不离道。",
      "logic_practice": "1) 明阴阳遁与甲隐之理；2) 排局并识三奇六仪；3) 定事体用神；4) 以门星宫气合断；5) 应期与方位并用验证。",
      "logic_compare": "较《奇门法窍》更重道与经义，较兵家奇门更玄理化；可视为以“元灵”为纲的奇门理论篇。"
    },
    {
      "name_han": "大六壬苗公射覆鬼撮脚",
      "logic_thesis": "射覆以六壬神将课式为眼，撮取物象之“脚”——即类神、五行、动静隐显的关键征象，以少驭多。",
      "logic_chain": "1) 起课得天地盘与四课三传；2) 定日辰与类神；3) 观神将所临与五行生克；4) 以“撮脚”抓主象（色形性用）；5) 合空亡刑害断真伪显隐；6) 射覆专精在象类敏捷，不在长篇。",
      "logic_practice": "1) 依时刻起壬课；2) 取用神/类神；3) 看将神所乘与落宫；4) 据五行物象比附；5) 校验空亡冲合定虚实。",
      "logic_compare": "较《大六壬心镜》更专射覆博弈，较《六壬视斯》更技巧口诀化；“鬼撮脚”名喻抓要害之象，属实用射覆秘本一路。"
    },
    {
      "name_han": "六壬视斯",
      "logic_thesis": "六壬断事须“视斯”——即当面审视课体结构：四课三传、贵神月将、遁干空亡，由形见义。",
      "logic_chain": "1) 先视课体格局是否成象；2) 次视三传发用与归宿；3) 再视神将乘临与日辰关系；4) 合遁干、空亡、刑冲破害；5) 以事类取用神对参；6) 结论由课象自显，忌先入为主。",
      "logic_practice": "1) 起课布四课三传；2) 标贵神月将遁干；3) 辨发用、中传、末传；4) 取事体用神；5) 综合刑冲空亡作断。",
      "logic_compare": "与《大六壬指南》同属课体正法，但“视斯”更强调观课入门顺序；较射覆专书更全面、较心镜更偏结构审视。"
    },
    {
      "name_han": "大六壬心镜",
      "logic_thesis": "壬学以“心镜”为喻：课如镜，心如光；理明则象现，象现则事应，心法与课法一体。",
      "logic_chain": "1) 立课为本，心明为用；2) 天地盘定时空框架；3) 神将课传显事机；4) 以生克旺衰断成败；5) 以类神定位人事；6) 镜明无翳则断语不歧。",
      "logic_practice": "1) 正规起课；2) 静心观课象主次；3) 定位类神与日辰；4) 推旺衰生克与应期；5) 对照事实验证修心法。",
      "logic_compare": "较《六壬视斯》更重心法与通贯，较《苗公射覆》更广及百事；属六壬理论与心诀并重的经典名号系统。"
    },
    {
      "name_han": "紫微斗数捷览",
      "logic_thesis": "斗数以命宫为纲、诸星安十二宫，捷览之旨在快速定位主星、辅曜、四化与宫干，形成可读命盘。",
      "logic_chain": "1) 由生时定命宫身宫；2) 安十四主星与辅星；3) 布十二宫人事分野；4) 查四化与干系；5) 以庙旺落陷与会照断吉凶；6) 捷览表格式利速查，不宜死记。",
      "logic_practice": "1) 排命盘定命身宫；2) 安紫微星系与天府星系；3) 定十二宫星曜；4) 看四化飞星；5) 综合宫干大限流年。",
      "logic_compare": "比《紫微斗数全书》简约便用，比子平更重星曜宫位结构；属速查型斗数入门/便览，重定位不重长论。"
    },
    {
      "name_han": "火珠林",
      "logic_thesis": "以钱代蓍起六爻，火珠林法将纳甲、世应、六亲、动变融为一体，使占筮可标准化操作与类断。",
      "logic_chain": "1) 三钱成爻，六次成卦；2) 纳甲装干支与六亲；3) 定世应与用神；4) 观动爻变卦生克；5) 合月建日辰空亡；6) 由用神旺衰应期断事。",
      "logic_practice": "1) 摇钱得本卦变卦；2) 装卦纳甲六亲；3) 定世应用神；4) 看动变生克冲合；5) 以日辰月建定应期。",
      "logic_compare": "对京房纳甲与《易林》传统作术数化定型，是后世六爻主流源头；较《天玄赋》更重起卦装卦程序，赋文则更重辞象。"
    },
    {
      "name_han": "天玄赋",
      "logic_thesis": "以赋体总括六爻/易占之象理：天玄者理，赋者辞；用神类象、动变刑冲皆以简练韵语固化推理。",
      "logic_chain": "1) 立用神为事之主；2) 以六亲五行归类人事；3) 动则生变，变则生克可见；4) 刑冲合害空亡定阻滞；5) 应期系于日月建与动爻；6) 赋文便于记诵，理在象外需活断。",
      "logic_practice": "1) 起卦定用神；2) 对照赋文类象条款；3) 查动变与日月；4) 断吉凶层次；5) 推应期与应验方式。",
      "logic_compare": "与《火珠林》配套：一书定法，一书赋象；较《黄金策》同类歌赋体系，同属六爻辞理记忆与推理模板。"
    }
  ]
}
